import{_ as a,o,c as t,a5 as c}from"./chunks/framework.BEZBAInb.js";const u=JSON.parse('{"title":"場景化資源","description":"","frontmatter":{"title":"場景化資源","order":8},"headers":[],"relativePath":"tc/latest/tutorial/core/scene-assets.md","filePath":"tc/latest/tutorial/core/scene-assets.md","lastUpdated":1788455378000}'),s={name:"tc/latest/tutorial/core/scene-assets.md"};function r(d,e,n,_,i,p){return o(),t("div",null,[...e[0]||(e[0]=[c('<h1 id="場景化資源" tabindex="-1">場景化資源 <a class="header-anchor" href="#場景化資源" aria-label="Permalink to &quot;場景化資源&quot;">​</a></h1><p>角色與背景項目現在參照 <code>PackedScene</code>。場景中可以放置圖片、影片、Spine、Live2D、shader 或自訂節點。</p><p>角色場景應繼承 <code>KonadoCharacterSceneBase</code>，並覆寫 <code>_apply_status(resolved_status_name, original_status_name)</code>；能驗證狀態名稱時也應覆寫 <code>_has_status</code>。延遲轉場可能在接受請求與最終套用時分別查詢，因此 <code>_has_status</code> 必須無副作用且具冪等性。能安全提供純紋理的場景可同時實作 <code>_get_current_status_transition_frame</code> 與 <code>_get_status_transition_frame</code>，透過 <code>KonadoCharacterTransitionFrame</code> 進行預乘 Alpha 交融。無法提供無副作用影格的 Live2D、Spine、影片和自訂場景會自動使用淡出、套用狀態、淡入的安全路徑；兩條路徑都不會複製角色場景。詳細設定請參閱<a href="./../script/actor/actor-change-state.html">演員切換狀態</a>。舞台動作應放在 <code>KonadoActorMotionLayer</code> 場景，其動畫名稱需與 KS 動作名稱一致。</p><p>每次要求狀態影格都必須回傳新建的獨立影格，不可在兩個轉場端點之間重複使用並改寫同一個可變物件。</p><p>背景場景應繼承 <code>KonadoBackgroundSceneBase</code>。如需使用鏡頭指令，請加入名稱唯一的 <code>KonadoCameraMarker</code>。這些節點只儲存目標機位的位置與縮放，實際畫面由對話範本中的相機繪製；請勿用 <code>KonadoCameraMarker</code> 取代自訂的繪製相機。內建轉場由 <code>KonadoBackgroundTransitionLayer</code> 處理，預設會透過 <code>SubViewport</code> 擷取完整場景。只有最終畫面與單張未修改的原始紋理完全一致時，才能選擇 <code>DIRECT_TEXTURE</code>；使用版面配置、變換、鏡頭、動畫、材質、染色或多個可繪製節點的背景必須保留 <code>VIEWPORT_CAPTURE</code>。</p>',5)])])}const m=a(s,[["render",r]]);export{u as __pageData,m as default};
